function userSearchControll() {
  if ($("#userCloud").length === 0) {
    return;
  }

  var params = new URLSearchParams(window.location.search);
  var cluster;

  if ($(".cloudbrain_debug").length === 1) {
    if (!params.get("cluster")) {
      cluster = $(".cloudbrain_debug").data("all-cluster");
    } else {
      if (params.get("cluster") === "resource_cluster_c2net") {
        cluster = $(".cloudbrain_debug").data("cluster-c2net");
      } else {
        cluster = $(".cloudbrain_debug").data("cluster-openi");
      }
    }
  }

  var jobType;

  if ($(".cloudbrain_debug").length === 1) {
    if (!params.get("jobType")) {
      jobType = $(".cloudbrain_debug").data("allTask");
    } else {
      if (params.get("jobType") === "DEBUG") {
        jobType = $(".cloudbrain_debug").data("debug-task");
      } else if (params.get("jobType") === "TRAIN") {
        jobType = $(".cloudbrain_debug").data("train-task");
      } else if (params.get("jobType") === "INFERENCE") {
        jobType = $(".cloudbrain_debug").data("inference-task");
      } else if (params.get("jobType") === "ONLINEINFERENCE") {
        jobType = $(".cloudbrain_debug").data("inferonline-task");
      } else if (params.get("jobType") === "HPC") {
        jobType = $(".cloudbrain_debug").data("supercompute-task");
      } else {
        jobType = $(".cloudbrain_debug").data("benchmark-task");
      }
    }
  }

  var aiCenter = !params.get("aiCenter") ? $(".cloudbrain_debug").data("all-aiCenter") : params.get("aiCenter");
  var listType = !params.get("listType") ? $(".cloudbrain_debug").data("all-compute") : params.get("listType");
  var jobStatus = !params.get("jobStatus") ? $(".cloudbrain_debug").data("all-status") : params.get("jobStatus").toUpperCase();
  var dropdownValueArray = [cluster, aiCenter, jobType, listType, jobStatus];
  $("#userCloud .default.text ").each(function (index, e) {
    index != 1 && $(e).text(dropdownValueArray[index]);
  });
}

function AdaminSearchControll() {
  if ($("#adminCloud").length === 0) {
    return;
  }

  var params = new URLSearchParams(window.location.search);
  var cluster;

  if ($(".cloudbrain_debug").length === 1) {
    if (!params.get("cluster")) {
      cluster = $(".cloudbrain_debug").data("all-cluster");
    } else {
      if (params.get("cluster") === "resource_cluster_c2net") {
        cluster = $(".cloudbrain_debug").data("cluster-c2net");
      } else {
        cluster = $(".cloudbrain_debug").data("cluster-openi");
      }
    }
  }

  var aiCenter = !params.get("aiCenter") ? $(".cloudbrain_debug").data("all-aiCenter") : params.get("aiCenter");
  var jobType = !params.get("jobType") ? $(".cloudbrain_debug").data("all-task") : params.get("jobType");
  var listType = !params.get("listType") ? $(".cloudbrain_debug").data("all-compute") : params.get("listType");
  var jobStatus = !params.get("jobStatus") ? $(".cloudbrain_debug").data("all-status") : params.get("jobStatus").toUpperCase();
  var dropdownValueArray = [cluster, aiCenter, jobType, listType, jobStatus];
  $("#adminCloud .default.text ").each(function (index, e) {
    index != 1 && $(e).text(dropdownValueArray[index]);
  });
}

userSearchControll();
AdaminSearchControll();
$(".message .close").on("click", function () {
  $(this).closest(".message").transition("fade");
});
/* MLU Debug List Operations */

$(".ui.basic.ai_mlu_debug").click(function () {
  var debug_button = $(".cloudbrain_debug").data("debug");
  var taskID = this.dataset.jobid;
  var linkPath = this.dataset.linkpath;
  var repoOwnerName = linkPath.split('/')[1];
  var repoName = linkPath.split('/')[2];

  if ($("#" + taskID + "-text").text() === "RUNNING") {
    $.ajax({
      type: 'get',
      url: "/api/v1/".concat(repoOwnerName, "/").concat(repoName, "/ai_task/debug_url?id=").concat(taskID),
      data: {
        _csrf: csrf
      },
      success: function success(res) {
        if (res.code == 0) {
          window.open(res.data.url);
        } else {
          $(".alert").html(res.msg).removeClass("alert-success").addClass("alert-danger").show().delay(3000).fadeOut();
        }
      },
      error: function error(err) {
        console.log(err);
      }
    });
  } else {
    $.ajax({
      type: 'post',
      url: "/api/v1/".concat(repoOwnerName, "/").concat(repoName, "/ai_task/restart?id=").concat(taskID),
      data: {
        _csrf: csrf
      },
      success: function success(res) {
        if (res.code == 0) {
          if (res.data.id != taskID) {
            window.location.reload();
          } else {
            $("#" + taskID + "-icon").removeClass().addClass(res.data.status);
            $("#" + taskID + "-text").text(res.data.status);
            $("#ai-debug-" + taskID).removeClass("blue").addClass("disabled");
            $("#ai-delete-" + taskID).removeClass("blue").addClass("disabled");
            $("#ai-debug-" + taskID).text(debug_button).css("margin", "0 1rem");
          }
        } else {
          $(".alert").html(res.msg).removeClass("alert-success").addClass("alert-danger").show().delay(3000).fadeOut();
        }
      },
      error: function error(err) {
        console.log(err);
      }
    });
  }
});
$(".ui.basic.ai_mlu_stop").click(function () {
  var debug_again_button = $(".cloudbrain_debug").data("debug-again");
  var ID = this.dataset.jobid;
  var bootFile = this.dataset.bootfile;
  var linkPath = this.dataset.linkpath;
  var repoOwnerName = linkPath.split('/')[1];
  var repoName = linkPath.split('/')[2];
  $.ajax({
    type: "post",
    url: "/api/v1/".concat(repoOwnerName, "/").concat(repoName, "/ai_task/stop?id=").concat(ID),
    data: {
      _csrf: csrf
    },
    success: function success(res) {
      if (res.code == "0") {
        $("#" + ID + "-icon").removeClass().addClass(res.data.status);
        $("#" + ID + "-text").text(res.data.status);

        if (res.data.status === "STOPPED") {
          if (!bootFile) {
            $("#ai-debug-" + ID).removeClass("disabled").addClass("blue").text(debug_again_button).css("margin", "0");
          } else {
            $("#ai-debug-" + ID).remove();
          }

          $("#ai-image-" + ID).removeClass("blue").addClass("disabled");
          $("#ai-model-debug-" + ID).removeClass("blue").addClass("disabled");
          $("#ai-delete-" + ID).removeClass("disabled").addClass("blue");
          $("#ai-stop-" + ID).removeClass("blue").addClass("disabled");
        } else {
          $("#ai-debug-" + ID).removeClass("blue").addClass("disabled");
          $("#ai-stop-" + ID).removeClass("blue").addClass("disabled");
        }
      } else {
        $(".alert").html(res.msg).removeClass("alert-success").addClass("alert-danger").show().delay(2000).fadeOut();
      }
    },
    error: function error(res) {
      console.log(res);
    }
  });
});
$(".ui.basic.ai_mlu_delete").click(function () {
  var ID = this.dataset.jobid;
  var linkPath = this.dataset.linkpath;
  var repoOwnerName = linkPath.split('/')[1];
  var repoName = linkPath.split('/')[2];
  var submitFlag = false;
  $(".ui.basic.modal").modal({
    onDeny: function onDeny() {
      submitFlag = false;
    },
    onApprove: function onApprove() {
      $.ajax({
        type: "post",
        url: "/api/v1/".concat(repoOwnerName, "/").concat(repoName, "/ai_task/del?id=").concat(ID),
        data: {
          _csrf: csrf
        },
        success: function success(res) {
          if (res.code == 0) {
            window.location.reload();
          } else {
            $(".alert").html(res.msg).removeClass("alert-success").addClass("alert-danger").show().delay(1500).fadeOut();
          }
        },
        error: function error(res) {
          console.log(res);
        }
      });
      submitFlag = true;
    },
    onHidden: function onHidden() {
      if (submitFlag == false) {
        $(".alert").html(i18n.canceled_operation).removeClass("alert-success").addClass("alert-danger").show().delay(1500).fadeOut();
      }
    }
  }).modal("show");
});

