function getNotice() {
  $('.notice-container .ui.dimmer').css('display', 'block');
  $.ajax({
    type: "GET",
    url: "/dashboard/invitation",
    dataType: "json",
    data: {
      filename: 'notice/notice.json'
    },
    success: function success(data) {
      $('.notice-container .ui.dimmer').css('display', 'none');
      var isZh = document.documentElement.getAttribute('lang') == 'zh-CN';
      if (!data) return;

      try {
        var noticeList = JSON.parse(data).Notices || [];
        var noticeEl = $('.notice-container');

        for (var i = 0, iLen = noticeList.length; i < iLen; i++) {
          var noticeObj = noticeList[i];
          noticeEl.append("<div class=\"notice-row\">\n            <div class=\"notice-title\">\n                <a class=\"_hm-notice\" href=\"".concat(noticeObj.Link, "\">\n                <i class=\"ri-arrow-right-s-line\" style=\"vertical-align:-2px;\"></i>\n                <span>").concat(isZh ? noticeObj.Title : noticeObj.Title_en || noticeObj.Title, "</span>\n              </a>\n            </div>\n            <div class=\"notice-time\">").concat(noticeObj.Date || '', "</div>\n          </div>"));
        }
      } catch (e) {
        console.info(e);
      }
    },
    error: function error(err) {
      $('.notice-container .ui.dimmer').css('display', 'none');
      console.info(err);
    }
  });
}

