function initNavbarContentToggle() {
  var content = $("#navbar-expand-content");
  var toggle = $("#navbar-expand-toggle");
  var isExpanded = false;
  toggle.on("click", function () {
    isExpanded = !isExpanded;

    if (isExpanded) {
      content.show();
      toggle.addClass("active");
    } else {
      content.hide();
      toggle.removeClass("active");
    }
  });
  $('.navbar-item-toggle-content').hide();
  $('.navbar-item-toggle').on('click', function (evt) {
    var self = $(this);
    if (evt.target.nodeName == 'A') return;
    var content = self.next('.navbar-item-toggle-content');
    var triangle = self.find('.triangle');

    if (content.is(':visible')) {
      content.hide();
    } else {
      content.show();
    }

    triangle.toggleClass('rotate');
  });
}

window.toggleDeadlineForm = function () {
  $("#deadlineForm").fadeToggle(150);
};

window.setDeadline = function () {
  var deadline = $("#deadlineDate").val();
  window.updateDeadline(deadline);
};

window.updateDeadline = function (deadlineString) {
  $("#deadline-err-invalid-date").hide();
  $("#deadline-loader").addClass("loading");
  var realDeadline = null;

  if (deadlineString !== "") {
    var newDate = Date.parse(deadlineString);

    if (Number.isNaN(newDate)) {
      $("#deadline-loader").removeClass("loading");
      $("#deadline-err-invalid-date").show();
      return false;
    }

    realDeadline = new Date(newDate);
  }

  $.ajax("".concat($("#update-issue-deadline-form").attr("action"), "/deadline"), {
    data: JSON.stringify({
      due_date: realDeadline
    }),
    headers: {
      "X-Csrf-Token": csrf,
      "X-Remote": true
    },
    contentType: "application/json",
    type: "POST",
    success: function success() {
      reload();
    },
    error: function error() {
      $("#deadline-loader").removeClass("loading");
      $("#deadline-err-invalid-date").show();
    }
  });
};

